            {
                foreach (var child in MenuItemAndChildren(item))
                    yield return child;
            }
        }

        IEnumerable<NSMenuItem> MenuItemAndChildren(NSMenuItem item)
        {
            yield return item;

            if (item.Submenu == null) yield break;

            foreach (var child in item.Submenu.Items)
            {
                foreach (var descendant in MenuItemAndChildren(child))
                    yield return descendant;
            }
        }

        bool IsProcessingOptionsCommand(NSMenuItem item)
        {
            switch (item.Identifier)
            {
                case LockProcessorMenuIdentifier:
                case ShowSplineHandlesMenuIdentifier:
                case AllowSplinePointTimeDraggingMenuIdentifier:
                case IntegrationRegionCopyIncludesStartMenuIdentifier:
                case ConvertToSmoothSplineMenuIdentifier:
                case ConvertToLinearSplineMenuIdentifier:
                case CopyToActiveMenuIdentifier:
                case CopyToNonProcessedMenuIdentifier:
                    return true;
                default:
                    return false;
            }
        }

        void UpdateProcessingOptionsMenu()
        {
            if (ProcessingOptionsMenuButton?.Menu == null) return;

            var hasProcessor = ContextIsValid && Processor?.Interpolator != null;
            var canEditProcessor = hasProcessor && !Processor.IsLocked;
            var splineInterpolator = Processor?.Interpolator as SplineInterpolator;
            var canConvertToSmoothSpline = canEditProcessor && Processor.Interpolator is PolynomialLeastSquaresInterpolator or SegmentedBaselineInterpolator;
            var canConvertToLinearSpline = canEditProcessor && (splineInterpolator == null || splineInterpolator.Algorithm != SplineInterpolator.SplineInterpolatorAlgorithm.Linear);
            var canConvertToAnySpline = canConvertToSmoothSpline || canConvertToLinearSpline;
            // Segmented conversion places points at segment ends, so the density does not apply.
            var canChooseConversionDensity = canConvertToAnySpline && Processor?.Interpolator is not SegmentedBaselineInterpolator;
            var hasSmoothSpline = splineInterpolator?.Algorithm == SplineInterpolator.SplineInterpolatorAlgorithm.Smooth;

            foreach (var item in ProcessingOptionsMenuItems())
            {
                switch (item.Identifier)
                {
                    case LockProcessorMenuIdentifier:
                        item.Title = Processor?.IsLocked == true ? "Unlock processor" : "Lock processor";
                        item.Enabled = hasProcessor;
                        break;
                    case ShowSplineHandlesMenuIdentifier:
                        item.Title = "Show spline handles";
                        item.Enabled = hasSmoothSpline;
                        item.State = splineInterpolator?.ShowHandles == true ? NSCellStateValue.On : NSCellStateValue.Off;
                        break;
                    case AllowSplinePointTimeDraggingMenuIdentifier:
                        item.Title = "Move spline points in time";
                        item.Enabled = splineInterpolator != null;
                        item.State = splineInterpolator?.AllowPointTimeDragging == true ? NSCellStateValue.On : NSCellStateValue.Off;
                        break;
                    case IntegrationRegionCopyIncludesStartMenuIdentifier:
                        item.Title = "Copy integration start to next";
                        item.Enabled = true;
                        item.State = AppSettings.IntegrationRegionCopyIncludesStart ? NSCellStateValue.On : NSCellStateValue.Off;
                        break;
                    case ConvertToSmoothSplineMenuIdentifier:
                        item.Enabled = canConvertToSmoothSpline;
                        break;
                    case ConvertToLinearSplineMenuIdentifier:
                        item.Enabled = canConvertToLinearSpline;
                        break;
                    case CopyToActiveMenuIdentifier:
                    case CopyToNonProcessedMenuIdentifier:
                        item.Enabled = hasProcessor;
                        break;
                    default:
                        if (item.Title == "Convert to spline")
                            item.Enabled = canConvertToAnySpline;
                        else if (item.Title == "Point Density")
                            item.Enabled = canChooseConversionDensity;
                        break;
                }
                if (ProcessingActivity.IsBusy && IsLiveProcessingCommand(item.Identifier))
                {
                    if (!idleMenuTooltips.ContainsKey(item)) idleMenuTooltips[item] = item.ToolTip;
                    item.Enabled = false;
                    item.ToolTip = FittingStatusPresentation.BusyTooltip;
                }
                else if (idleMenuTooltips.TryGetValue(item, out var tooltip))
                {
                    item.ToolTip = tooltip;
                    idleMenuTooltips.Remove(item);
                }
            }

            if (SplineConversionPointDensityControl != null)
                SplineConversionPointDensityControl.Enabled = canChooseConversionDensity;

            if (ConvertToLinearSplineButton != null)
                ConvertToLinearSplineButton.Enabled = canConvertToLinearSpline;

            if (ConvertToSmoothSplineButton != null)
                ConvertToSmoothSplineButton.Enabled = canConvertToSmoothSpline;

            if (SplinePointDensityControl != null)
                SplinePointDensityControl.Enabled = splineInterpolator != null;
            calculationControls?.Refresh();
        }

        void UpdateProcessingLockUI()
        {
            UpdateProcessingCopyUI();
            var hasProcessor = ContextIsValid && Processor?.Interpolator != null;
            var isLocked = hasProcessor && Processor.IsLocked;
            var hasInjections = hasProcessor && Data.Injections.Count > 0;
            var baselineEditingEnabled = hasProcessor && !isLocked;
            var integrationEditingEnabled = hasInjections && !isLocked;
            var splineSelected = Processor?.Interpolator is SplineInterpolator;
            var polynomialSelected = Processor?.Interpolator is PolynomialLeastSquaresInterpolator or SegmentedBaselineInterpolator;
            var splineInterpolator = Processor?.Interpolator as SplineInterpolator;
            var hasSmoothSpline =
                splineInterpolator?.Algorithm
                == SplineInterpolator.SplineInterpolatorAlgorithm.Smooth;

            ProcessingLockedImage.Hidden = !isLocked;
            ProcessingLockButton.Enabled = hasProcessor;
            ProcessingLockButton.Title = isLocked ? "Unlock" : "Lock";

            InterpolatorTypeControl.Enabled = baselineEditingEnabled;
            SplineAlgoControl.Enabled = baselineEditingEnabled && splineSelected;
            SplinePointDensityControl.Enabled = baselineEditingEnabled && splineSelected;
            SplineHandleModeControl.Enabled = baselineEditingEnabled && splineSelected;
            PolynomialDegreeSlider.Enabled = baselineEditingEnabled && polynomialSelected;

            if (ShowSplineHandlesButton != null)
            {
                ShowSplineHandlesButton.Enabled = hasSmoothSpline;
                ShowSplineHandlesButton.State = splineInterpolator?.ShowHandles == true
                    ? NSCellStateValue.On
                    : NSCellStateValue.Off;
            }

            if (AllowSplinePointTimeDraggingButton != null)
            {
                AllowSplinePointTimeDraggingButton.Enabled = splineSelected;
                AllowSplinePointTimeDraggingButton.State =
                    splineInterpolator?.AllowPointTimeDragging == true
                        ? NSCellStateValue.On
                        : NSCellStateValue.Off;
            }

            FitPeaksButton.Enabled = hasInjections && !isLocked;
            IntegrationDelayControl.Enabled = integrationEditingEnabled;
            IntegrationLengthControl.Enabled = integrationEditingEnabled;
            CopyToNextButton.Enabled = integrationEditingEnabled &&
                BaselineGraphView.SelectedPeak >= 0 &&
                BaselineGraphView.SelectedPeak < BaselineGraphView.Data.InjectionCount - 1;
            calculationControls?.Refresh();
        }

