        void ToggleProcessingLock()
        {
            using var activity = ProcessingActivity.TryBegin();
            if (activity == null) return;
            using var ownership = activity.Enter();
            if (!ContextIsValid || Processor?.Interpolator == null) return;

            Processor.ToggleLock();
            UpdateUI();
        }

        partial void ProcessingLockButtonClicked(NSButton sender) => ToggleProcessingLock();

        void ProcessingOptionsMenuItemActivated(object sender, EventArgs e)
        {
            if (sender is not NSMenuItem item) return;
            if (ProcessingActivity.IsBusy && IsLiveProcessingCommand(item.Identifier)) return;

            var splineInterpolator = Processor?.Interpolator as SplineInterpolator;

            switch (item.Identifier)
            {
                case LockProcessorMenuIdentifier:
                    ToggleProcessingLock();
                    break;
                case ShowSplineHandlesMenuIdentifier:
                    if (splineInterpolator == null || splineInterpolator.Algorithm != SplineInterpolator.SplineInterpolatorAlgorithm.Smooth) return;
                    splineInterpolator.ShowHandles = !splineInterpolator.ShowHandles;
                    UpdateUI();
                    BaselineGraphView.Invalidate();
                    break;
                case AllowSplinePointTimeDraggingMenuIdentifier:
                    if (splineInterpolator == null) return;
                    splineInterpolator.AllowPointTimeDragging = !splineInterpolator.AllowPointTimeDragging;
                    UpdateUI();
                    BaselineGraphView.Invalidate();
                    break;
                case IntegrationRegionCopyIncludesStartMenuIdentifier:
                    AppSettings.IntegrationRegionCopyIncludesStart = !AppSettings.IntegrationRegionCopyIncludesStart;
                    AppSettings.Save();
                    UpdateUI();
                    break;
                case ConvertToSmoothSplineMenuIdentifier:
                    ConvertCurrentProcessorToSpline(SplineInterpolator.SplineInterpolatorAlgorithm.Smooth);
                    break;
                case ConvertToLinearSplineMenuIdentifier:
                    ConvertCurrentProcessorToSpline(SplineInterpolator.SplineInterpolatorAlgorithm.Linear);
                    break;
                case CopyToActiveMenuIdentifier:
                    CopyProcessing(DataManager.CopySelectedProcessToActive);
                    break;
                case CopyToNonProcessedMenuIdentifier:
                    CopyProcessing(DataManager.CopySelectedProcessToNonProcessed);
                    break;
            }
        }

        static bool IsLiveProcessingCommand(string identifier) => identifier is
            LockProcessorMenuIdentifier or ConvertToSmoothSplineMenuIdentifier or ConvertToLinearSplineMenuIdentifier
            or CopyToActiveMenuIdentifier or CopyToNonProcessedMenuIdentifier;

        async void ConvertCurrentProcessorToSpline(SplineInterpolator.SplineInterpolatorAlgorithm algorithm)
        {
            using var activity = ProcessingActivity.TryBegin();
            if (activity == null) return;
            using var ownership = activity.Enter();
            if (!ContextIsValid || Processor?.Interpolator == null || Processor.IsLocked) return;

            if (Processor.Interpolator is SplineInterpolator splineInterpolator)
            {
                if (algorithm != SplineInterpolator.SplineInterpolatorAlgorithm.Linear) return;
                if (splineInterpolator.Algorithm == SplineInterpolator.SplineInterpolatorAlgorithm.Linear) return;

                splineInterpolator.Algorithm = SplineInterpolator.SplineInterpolatorAlgorithm.Linear;
                splineInterpolator.ApplyPointDensity();
                _ = Processor.ProcessData(false);
                UpdateUI();
                return;
            }

            if (algorithm == SplineInterpolator.SplineInterpolatorAlgorithm.Smooth && Processor.Interpolator is not PolynomialLeastSquaresInterpolator and not SegmentedBaselineInterpolator) return;

            SplineInterpolator.PolynomialToSplineConversionTargetAlgorithm = algorithm;
            await Processor.Interpolator.ConvertToSplineAsync(ProductSplinePointDensity(algorithm));
            UpdateUI();
        }

        partial void ConvertToLinearSplineClicked(NSButton sender)
        {
            ConvertCurrentProcessorToSpline(SplineInterpolator.SplineInterpolatorAlgorithm.Linear);
        }

        partial void ConvertToSmoothSplineClicked(NSButton sender)
        {
            ConvertCurrentProcessorToSpline(SplineInterpolator.SplineInterpolatorAlgorithm.Smooth);
        }

        int ProductSplinePointDensity(SplineInterpolator.SplineInterpolatorAlgorithm algorithm)
        {
            var densitySegment = SplineConversionPointDensityControl?.SelectedSegment ?? 1;

            return algorithm switch
            {
                SplineInterpolator.SplineInterpolatorAlgorithm.Linear => (int)densitySegment switch
                {
                    0 => 2,
                    1 => 4,
                    2 => 6,
                    _ => 4,
                },
                _ => (int)densitySegment switch
                {
                    0 => 1,
                    1 => 2,
                    2 => 3,
                    _ => 2,
                },
            };
        }

        void SetSelectedSegment(NSSegmentedControl control, int segment)
        {
            for (int i = 0; i < control.SegmentCount; i++) control.SetSelected(false, i);

            if (segment > -0.5) control.SetSelected(true, segment);
        }

