            SetSelectedSegment(PeakZoomSegControl, BaselineGraphView.CurrentHorizontalZoomMode switch
            {
                DataProcessingGraphView.HorizontalZoomMode.AllPeaks => 0,
                DataProcessingGraphView.HorizontalZoomMode.SelectedPeak => 1,
                _ => -1
