        #region Processing Injections

        async partial void FitPeaksClicked(NSButton sender)
        {
            using var activity = ProcessingActivity.TryBegin();
            if (activity == null) return;
            using var ownership = activity.Enter();
            if (!ContextIsValid || Data.Injections.Count == 0) return;

            try
            {
                var fitResult = await Data.FitIntegrationPeaksAsync();

                var selectedPeak = BaselineGraphView.SelectedPeak;
                IntegrationLengthControl.FloatValue = selectedPeak >= 0 && selectedPeak < Data.Injections.Count
                    ? Data.Injections[selectedPeak].IntegrationEndOffset
                    : Data.Injections.Last().IntegrationEndOffset;
                UpdateSliderLabels();

                BaselineGraphView.Invalidate();
                StatusBarManager.SetStatus(PeakFitStatusMessage(fitResult), 3000);
            }
            catch (Exception ex)
            {
                AppEventHandler.DisplayHandledException(ex);
            }
        }

        partial void IntegrationStartTimeSliderChanged(NSSlider sender)
        {
            using var activity = integrationSliderActivity == null ? ProcessingActivity.TryBegin() : null;
            if (activity == null && integrationSliderActivity == null) return;
            using var ownership = (integrationSliderActivity ?? activity).Enter();
            if (!AcceptIntegrationSliderAction(sender)) return;
            UpdateSliderLabels();
            UpdateIntegrationStartTime(IntegrationDelayControl.FloatValue, !IntegrationDelayControl.IsTrackingRange);
        }

        partial void IntegrationLengthSliderChanged(NSSlider sender)
        {
            using var activity = integrationSliderActivity == null ? ProcessingActivity.TryBegin() : null;
            if (activity == null && integrationSliderActivity == null) return;
            using var ownership = (integrationSliderActivity ?? activity).Enter();
            if (!AcceptIntegrationSliderAction(sender)) return;
            UpdateSliderLabels();
            UpdateIntegrationEndPoint(time_or_factor: GetLengthSliderParameter(), refreshBaseline: !IntegrationLengthControl.IsTrackingRange);
        }

        void IntegrationSliderTrackingStarted(object sender, EventArgs e)
        {
            integrationSliderActivity = ProcessingActivity.TryBegin();
            if (integrationSliderActivity == null) return;
            trackingIntegrationSlider = (IntegrationRangeSlider)sender;
            integrationSliderOwner = Data;
            integrationSliderLastValue = trackingIntegrationSlider.DoubleValue;
            integrationSliderChanged = false;
        }

        bool AcceptIntegrationSliderAction(NSSlider sender)
        {
            if (!ContextIsValid || Processor.IsLocked) return false;
            if (!(sender is IntegrationRangeSlider slider) || !slider.IsTrackingRange) return true;
            if (!ReferenceEquals(slider, trackingIntegrationSlider)
                || !ReferenceEquals(Data, integrationSliderOwner)) return false;
            if (slider.DoubleValue == integrationSliderLastValue) return false;

            integrationSliderLastValue = slider.DoubleValue;
            integrationSliderChanged = true;
            return true;
        }

        void IntegrationSliderTrackingCompleted(object sender, EventArgs e)
        {
            if (!ReferenceEquals(sender, trackingIntegrationSlider)) return;
            using var activity = integrationSliderActivity;
            integrationSliderActivity = null;
            if (activity == null) return;
            using var ownership = activity.Enter();
            var publish = integrationSliderChanged && ReferenceEquals(Data, integrationSliderOwner);
            trackingIntegrationSlider = null;
            integrationSliderOwner = null;
            integrationSliderChanged = false;
            if (!publish || !ContextIsValid || Processor.IsLocked) return;

            if (Processor.DiscardIntegratedPoints) UpdateProcessing();
            else Processor.IntegratePeaks();
        }

        float GetLengthSliderParameter() => Processor.IntegrationLengthMode switch
        {
            // A factor from 1-5
            InjectionData.IntegrationLengthMode.Factor => (float)Math.Pow(5, IntegrationLengthControl.FloatValue / IntegrationLengthControl.MaxValue),
            // After Fit Peaks the control shows a fitted end point in seconds.
            InjectionData.IntegrationLengthMode.Fit => IntegrationLengthControl.FloatValue,
            // Time mode, return the slider value
            InjectionData.IntegrationLengthMode.Time => IntegrationLengthControl.FloatValue,
            _ => IntegrationLengthControl.FloatValue
        };


        float FactorToSlider(float value)
        {
            return (float)(Math.Log(value, 5) * IntegrationLengthControl.MaxValue);
        }

        void UpdateIntegrationEndPoint(float time_or_factor, bool refreshBaseline = true, bool process = true)
        {
            if (!ContextIsValid || Processor.IsLocked) return;

            try
            {
                switch (Processor.IntegrationLengthMode)
                {
                    case InjectionData.IntegrationLengthMode.Time:
                        if (BaselineGraphView.SelectedPeak == -1) Data.SetIntegrationLengthByTime(time_or_factor);
                        else Data.Injections[BaselineGraphView.SelectedPeak].SetIntegrationLengthByTime(time_or_factor);
                        break;
                    case InjectionData.IntegrationLengthMode.Factor:
                        Processor.IntegrationLengthFactor = time_or_factor;
                        if (BaselineGraphView.SelectedPeak == -1) Data.SetIntegrationLengthByFactor(time_or_factor);
                        else Data.Injections[BaselineGraphView.SelectedPeak].SetIntegrationLengthByFactor(time_or_factor);
                        break;
                    case InjectionData.IntegrationLengthMode.Fit:
                        // A set end point replaces the Fit Peaks record.
                        Processor.IntegrationLengthMode = InjectionData.IntegrationLengthMode.Time;
                        if (BaselineGraphView.SelectedPeak == -1) Data.SetIntegrationLengthByTime(time_or_factor);
                        else Data.Injections[BaselineGraphView.SelectedPeak].SetIntegrationLengthByTime(time_or_factor);
                        break;
                }

                BaselineGraphView.Invalidate();

                // Initialization supplies the endpoint before its single awaited processing pass.
                if (!process) return;

                if (refreshBaseline && Processor.DiscardIntegratedPoints)
                    UpdateProcessing();
                else
                    Data.Processor.IntegratePeaks(invalidate: refreshBaseline, notify: refreshBaseline);
            }
            catch (Exception ex)
            {
                AppEventHandler.DisplayHandledException(ex);
            }
        }

        static string PeakFitStatusMessage(PeakFitResult result) => result.Status switch
        {
            PeakFitStatus.Converged => $"Injection heat peaks fitted succesfully",
            PeakFitStatus.CycleResolved => "Peaks fitted; a stable cycle was resolved",
            PeakFitStatus.NonConvergent => "Peak fitting did not converge; integration regions were unchanged",
            PeakFitStatus.NoData => "No peak data available to fit",
            PeakFitStatus.Locked => "Peak fitting skipped because processing is locked",
            _ => "Peak fitting failed; integration regions were unchanged",
        };

        void UpdateIntegrationStartTime(float delay, bool refreshBaseline = true)
        {
            if (!ContextIsValid || Processor.IsLocked) return;

            if (BaselineGraphView.SelectedPeak == -1) Data.Injections.ForEach(inj => inj.SetIntegrationStartTime(delay));
            else Data.Injections[BaselineGraphView.SelectedPeak].SetIntegrationStartTime(delay);

            BaselineGraphView.Invalidate();

            if (refreshBaseline && Processor.DiscardIntegratedPoints)
                UpdateProcessing();
            else
                Data.Processor.IntegratePeaks(invalidate: refreshBaseline, notify: refreshBaseline);
        }

